<template>
<section id="radio-map" class="radio-map">
 <header><div><small>NETWORK ATLAS / LAYERS</small><h2>网络探索地图</h2></div><button :aria-expanded="opened" aria-controls="radio-map-content" @click="opened=!opened">{{opened?'收起地图':'打开多图层地图'}}</button></header>
 <div v-if="opened" id="radio-map-content">
 <p class="intro">一张地图，探索电台与海底网络。可单独显示或叠加图层，点击地区找频道、点击光缆查连接。</p>
 <div class="layer-toolbar" aria-label="地图图层控制"><label><input v-model="showRadio" type="checkbox"/>电台图层</label><label><input v-model="showCables" type="checkbox"/>海底光缆图层</label><label><input v-model="showProvinces" type="checkbox"/>省级分界</label><label><input v-model="showNames" type="checkbox"/>省份名称</label><select v-model="mapView" aria-label="地图视野"><option value="china">中国视野</option><option value="world">全球视野</option></select></div>
 <div v-if="showRadio" class="filters"><input v-model="query" type="search" aria-label="地图搜索电台" placeholder="搜索电台、城市或类型…"/><select v-model="region" aria-label="地图电台地区"><option value="">全部地区</option><option v-for="r in regions" :key="r.name" :value="r.name">{{r.name}} · {{r.count}}</option><option v-for="r in unlocated" :key="r" :value="r">{{r}} · 未定位目录</option></select><select v-model="category" aria-label="地图电台类型"><option value="">全部类型</option><option v-for="c in categories" :key="c">{{c}}</option></select><button @click="reset">重置筛选</button></div>
 <div class="map-layout"><div class="map-side"><div class="map-status"><span>{{regions.length}} 个地区 · {{stations.length}} 个目录频道</span><span>地区聚合 · 非发射台坐标</span></div>
 <svg :viewBox="mapView==='china' ? '750 90 240 170' : '0 0 1080 540'" class="radio-atlas" role="group" aria-label="电台与海底光缆多图层地图"><rect x="0" y="0" width="1080" height="540" fill="#0a1c2b"/><path v-for="(d,i) in land" :key="i" :d="d" class="land"/>
 <g v-if="showProvinces" class="province-layer"><g v-for="(p,i) in provinces" :key="i"><path v-for="(d,j) in p.paths" :key="j" :d="d" class="province" :class="{selected:region===p.name}" :role="p.name?'button':undefined" :tabindex="p.name?0:undefined" :aria-label="p.name ? '选择地区 '+p.name : undefined" @click="p.name && selectRegion(p.name)" @keydown.enter.prevent="p.name && selectRegion(p.name)" @keydown.space.prevent="p.name && selectRegion(p.name)"><title>{{p.fullName}}</title></path></g></g>
 <g v-if="showCables" class="cable-layer"><g v-for="c in cables" :key="c.id" role="button" tabindex="0" :aria-label="'查看光缆 '+c.name" @click="selectedCable=c.id" @keydown.enter.prevent="selectedCable=c.id" @keydown.space.prevent="selectedCable=c.id"><path v-for="(d,i) in paths(c.points)" :key="i" :d="d" fill="none" :stroke="c.color" :stroke-width="selectedCable===c.id?3:1.5" vector-effect="non-scaling-stroke"/><path v-for="(d,i) in paths(c.points)" :key="'hit'+i" :d="d" fill="none" stroke="transparent" stroke-width="14" vector-effect="non-scaling-stroke"><title>{{c.name}}</title></path></g></g>
 <g v-if="showRadio" class="radio-layer"><g v-for="r in regions" :key="r.name" class="region-marker" role="button" tabindex="0" :aria-label="`${r.name} ${r.count} 个电台`" :aria-pressed="region===r.name" @click="selectRegion(r.name)" @keydown.enter.prevent="selectRegion(r.name)" @keydown.space.prevent="selectRegion(r.name)"><circle :cx="project(...r.coordinates)[0]" :cy="project(...r.coordinates)[1]" :r="mapView==='world'?2:1.5" :class="{active:region===r.name}"/><title>{{r.name}} · {{r.count}} 个目录频道</title></g></g>
 <g v-if="showNames && mapView==='china'" class="province-names"><text v-for="p in provinces.filter(p=>p.name && p.center)" :key="p.name" :x="project(...p.center)[0]" :y="project(...p.center)[1]-2" text-anchor="middle">{{p.name}}</text></g>
 </svg>
 <p v-if="mapError" role="status">底图加载失败，仍可通过地区按钮筛选。<button @click="loadLand">重试底图</button></p>
 <div v-if="showRadio" class="region-buttons" aria-label="按地区浏览电台"><button v-for="r in regions" :key="r.name" :aria-pressed="region===r.name" @click="selectRegion(r.name)">{{r.name}} <small>{{r.count}}</small></button></div>
 <p class="note">标记采用省级行政区首府或代表城市的近似位置，仅用于浏览分类，不表示电台总部、发射台或覆盖范围；目录未定位频道保留在地区下拉框中。陆地底图：Natural Earth；省级边界：阿里云 DataV 地理数据。</p>
 </div><aside class="station-panel"><div v-if="showCables" class="cable-directory"><h3>海底光缆</h3><p class="note">7 条精选连接示意，非实际海床走向、完整目录或实时运行状态。切换全球视野查看跨洲线路。</p><select v-model="selectedCable" aria-label="选择光缆"><option v-for="c in cables" :key="c.id" :value="c.id">{{c.name}} · {{c.region}}</option></select><article><h4>{{currentCable.name}}</h4><p>{{currentCable.note}}</p><ul><li v-for="p in currentCable.points" :key="p.name">{{p.name}}</li></ul><a :href="currentCable.source" target="_blank" rel="noopener noreferrer">查看线路资料 ↗</a></article></div><p v-if="!showCables && !showRadio">请选择电台或海底光缆图层。</p><div v-if="showRadio"><div class="panel-heading"><h3>{{region||'全部地区'}}</h3><span>{{visible.length}} 个匹配频道</span></div><p class="note">点击收听会打开顶部电台面板，可收藏、调节音量和设置定时关闭。源状态来自目录快照，不保证当前可播放。</p>
 <ul><li v-for="s in paged" :key="s.id"><button class="station-play" :aria-label="'收听 '+s.name" @click="listen(s)"><strong>{{s.name}}</strong><small>{{s.region}} {{s.city}} · {{s.categories.join(' / ')}}</small><small>{{s.availability==='reachable'?'目录检测：源可访问':s.availability==='unavailable'?'目录检测：暂不可用':'目录检测：未检测'}} <span>▶ 收听</span></small></button></li></ul><p v-if="!visible.length">没有匹配电台，请调整筛选条件。</p><nav v-if="pages>1" aria-label="地图电台分页"><button :disabled="page<=1" @click="page--">上一页</button><span>{{page}} / {{pages}}</span><button :disabled="page>=pages" @click="page++">下一页</button></nav><p role="status">{{notice}}</p>
 </div></aside></div>
 <footer>目录快照 {{date}} · {{directory.scope}}。收听由原播放器处理，保留收藏、播放互斥和定时关闭。</footer>
 </div>
</section>
</template>
<script>
import directory from '../data/china-radio-directory.json';
import {filterRadioDirectory,mergeRadioDirectory} from '../utils/radio-directory.mjs';
import {groupRadioRegions,regionCenters,provinceShapes} from '../utils/radio-map.mjs';
import {landPaths,project,cables,connectionPaths} from '../utils/submarine-cables.mjs';
export default {name:'RadioMap',emits:['play-station'],data:()=>({opened:false,showRadio:true,showCables:false,showProvinces:true,showNames:true,mapView:'china',provinces:[],cables,selectedCable:'marea',directory,stations:mergeRadioDirectory([],directory.stations),region:'',query:'',category:'',page:1,land:[],mapError:false,notice:'',controller:null}),computed:{currentCable(){return this.cables.find(c=>c.id===this.selectedCable)||this.cables[0];},regions(){return groupRadioRegions(this.stations);},unlocated(){return [...new Set(this.stations.map(s=>s.region))].filter(r=>!regionCenters[r]).sort();},categories(){return [...new Set(this.stations.flatMap(s=>s.categories||[]))];},visible(){return filterRadioDirectory(this.stations,this);},pages(){return Math.max(1,Math.ceil(this.visible.length/12));},paged(){return this.visible.slice((this.page-1)*12,this.page*12);},date(){return new Date(directory.generatedAt).toLocaleDateString('zh-CN');}},watch:{opened(v){if(v&&!this.land.length)this.loadLand();},region(){this.page=1;this.notice='';},query(){this.page=1;},category(){this.page=1;}},beforeUnmount(){this.controller?.abort();},methods:{project,paths:connectionPaths,selectRegion(name){this.region=this.region===name?'':name;},reset(){this.region='';this.query='';this.category='';this.page=1;this.notice='';},listen(s){this.notice='已选择 '+s.name+'，请查看顶部电台播放器的连接状态。';this.$emit('play-station',s);},async loadLand(){this.controller?.abort();this.controller=new AbortController();this.mapError=false;try{const r=await fetch(`${process.env.BASE_URL}maps/land.geojson`,{signal:this.controller.signal});if(!r.ok)throw new Error();this.land=landPaths(await r.json());const boundaries=await fetch(`${process.env.BASE_URL}maps/china-provinces.geojson`,{signal:this.controller.signal});if(!boundaries.ok)throw new Error();this.provinces=provinceShapes(await boundaries.json(),landPaths);}catch(e){if(e.name!=='AbortError')this.mapError=true;}}}};
</script>
<style scoped>
