ng span{font-size:11px;opacity:.7}.station-panel ul{list-style:none;margin:12px 0;padding:0;max-height:440px;overflow:auto}.station-panel li{margin:7px 0}.station-play{display:block;width:100%;text-align:left}.station-play strong,.station-play small{display:block;overflow-wrap:anywhere}.station-play small{font-size:10px;opacity:.7;margin-top:4px}.station-play span{float:right;color:var(--ui-accent,#398c5a)}.note,footer{font-size:11px;line-height:1.8;opacity:.72}.intro{line-height:1.8}footer{margin-top:16px;border-top:1px solid var(--el-border-color,#d7e4dc);padding-top:12px}nav{font-size:11px}@media(max-width:1050px){.map-layout{grid-template-columns:1fr}.station-panel ul{max-height:350px}}@media(max-width:600px){.radio-map{margin:16px 12px;padding:14px}.filters input{flex-basis:100%}.filters select{flex:1;min-width:0}.station-panel{padding:12px}}
